const $=selector=>document.querySelector(selector);
let authenticated=false,setupRequired=false,checking=false,toastTimer;
function toast(message){clearTimeout(toastTimer);$('#toast').textContent=message;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,6000)}
function safeNext(value){try{const url=new URL(value,location.origin);if(url.origin===location.origin&&/^\/(vovrema|gym|tasks)(\/|$)/.test(url.pathname))return url.pathname+url.search+url.hash}catch{}return null}
const next=safeNext(new URLSearchParams(location.search).get('next'));
async function api(path,body){const response=await fetch('/api/'+path,{method:body===undefined?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:body===undefined?{}:{'Content-Type':'application/json'},body:body===undefined?undefined:JSON.stringify(body)});const data=await response.json();if(!response.ok){if(response.status===401&&authenticated){authenticated=false;showSession()}throw Error(data.error||'Не удалось выполнить запрос')}return data}
function showSession(){$('main').hidden=!authenticated;$('#auth').hidden=authenticated;$('#logout').hidden=!authenticated;$('#setup-fields').hidden=!setupRequired;$('#setup-fields').disabled=!setupRequired;$('#auth-title').textContent=setupRequired?'Создать общий пароль':'С возвращением';$('#password').autocomplete=setupRequired?'new-password':'current-password';$('#auth-submit').textContent=setupRequired?'Сохранить пароль и войти':'Войти'}
async function boot(){if(checking)return;checking=true;$('#retry').hidden=true;try{const status=await api('session');authenticated=status.authenticated;setupRequired=status.setupRequired;showSession();$('#auth-submit').disabled=false;if(authenticated){if(next){location.replace(next);return}window.pushRefresh?.()}}catch{$('#auth-submit').disabled=true;$('#auth-error').textContent='Не удалось связаться с сервером. Проверь подключение и повтори попытку.';$('#retry').hidden=false}finally{checking=false}}
$('#auth-form').onsubmit=async event=>{event.preventDefault();$('#auth-error').textContent='';const password=$('#password').value;if(setupRequired&&password!==$('#password-confirm').value){$('#auth-error').textContent='Пароли не совпадают';return}$('#auth-submit').disabled=true;try{await api(setupRequired?'setup':'login',{password,token:$('#setup-token').value});$('#password').value='';$('#password-confirm').value='';await boot()}catch(error){$('#auth-error').textContent=error.message}finally{$('#auth-submit').disabled=false}};
$('#logout').onclick=async()=>{try{await api('logout',{});authenticated=false;showSession()}catch(error){toast(error.message)}};
$('#retry').onclick=boot;
$('#today').textContent=new Intl.DateTimeFormat('ru',{weekday:'long',day:'numeric',month:'long'}).format(new Date());
const token=new URLSearchParams(location.hash.slice(1)).get('setup');if(token){$('#setup-token').value=token;history.replaceState(null,'',location.pathname+location.search)}
window.addEventListener('focus',boot);document.addEventListener('visibilitychange',()=>{if(!document.hidden)boot()});boot();
